module TopModule (
    input  wire        clk,
    input  wire        reset,
    output reg  [31:0] q
);

    // Galois LFSR, 32 bits, taps at bit positions 32, 22, 2, 1 (1-indexed)
    // -> mask bits 31, 21, 1, 0 = 32'h8020_0003
    // Shift right; if q[0] is set, XOR the tapped positions with q[0].
    always @(posedge clk) begin
        if (reset)
            q <= 32'h0000_0001;
        else
            q <= (q >> 1) ^ (q[0] ? 32'h8020_0003 : 32'h0000_0000);
    end

endmodule
```

**Explanation**
- A Galois LFSR shifting right computes `q_next = (q >> 1)`, then XORs the tapped bit positions with the LSB output `q[0]`.
- Taps at (1-indexed) positions 32, 22, 2, 1 map to bit indices 31, 21, 1, 0, giving the feedback mask `32'h8020_0003` (`1<<31 | 1<<21 | 1<<1 | 1<<0`).
- The mask is applied only when `q[0] == 1`, which is equivalent to XORing the tapped positions with `q[0]`.
- Reset is synchronous and active high, loading the seed value `32'h1` (an LFSR must not be reset to zero, or it would lock up).

